// The system_prompt parameter "suggests" an AI role (system prompt)

const Gpt_Client = require('gpt4free-client');

async function main() {
  const completion = new Gpt_Client.Completion();

  await completion.create({
    system_prompt: "You are AI copy of DaniilSV, the best brawl stars mod creator", // system_prompt
    messages: [{ role: 'user', content: 'hello world' }] // messages
  });

  for await (const chunk of completion) {
    console.log(chunk);
  }
}

main()